$id=(int)($_GET['id']??0);
$stmt=db()->prepare("SELECT n.*, e.nombre empresa, e.clave empresa_clave, u.nombre disenador FROM v2_notas n JOIN v2_empresas e ON e.id=n.empresa_id LEFT JOIN v2_usuarios u ON u.id=n.disenador_id WHERE n.id=?"); $stmt->execute([$id]); $n=$stmt->fetch();
if(!$n){ flash('danger','Nota no encontrada.'); redirect_to('notas.php'); }
if(role_in(['disenador','externo']) && (int)$n['disenador_id'] !== (int)current_user()['id']){ flash('danger','No tienes permiso para ver esta nota.'); redirect_to('mis_notas.php'); }
$stmt=db()->prepare("SELECT p.*, c.nombre catalogo FROM v2_nota_partidas p LEFT JOIN v2_catalogo_items c ON c.id=p.catalogo_id WHERE p.nota_id=? ORDER BY p.id"); $stmt->execute([$id]); $partidas=$stmt->fetchAll();
$stmt=db()->prepare("SELECT p.*, u.nombre usuario FROM v2_pagos p LEFT JOIN v2_usuarios u ON u.id=p.usuario_id WHERE p.nota_id=? ORDER BY p.fecha_pago,p.id"); $stmt->execute([$id]); $pagos=$stmt->fetchAll();
$stmt=db()->prepare("SELECT m.*, ur.nombre reporta, resp.nombre responsable FROM v2_mermas m LEFT JOIN v2_usuarios ur ON ur.id=m.reportado_por_id LEFT JOIN v2_usuarios resp ON resp.id=m.responsable_probable_id WHERE m.nota_id=? ORDER BY m.fecha_merma,m.id"); $stmt->execute([$id]); $mermas=$stmt->fetchAll();
$stmt=db()->prepare("SELECT c.*, u.nombre disenador FROM v2_comisiones c JOIN v2_usuarios u ON u.id=c.disenador_id WHERE c.nota_id=? ORDER BY c.id"); $stmt->execute([$id]); $comisiones=$stmt->fetchAll();
$users=usuarios_activos(); $dis=disenadores();
